/// The text roles, each a Dynamic Type style (or a size scaled with one), so
/// every one grows with the pilot's text size.
enum WingtipType {
    /// A name over a card's picture: iOS's Title 1, as Maps sets a place's over its photos.
    static let hero: Font = Font.system(.title, weight: .bold)
    /// A card's name: an airport's, the airspace's, Nearest's (iOS Title 2).
    static let card: Font = Font.system(.title2, weight: .bold)
    /// A section's title in the panel's tabs (iOS Title 3), 20 with a mouse too (decision 0021).
    static let heading: Font = Font.system(.title3, weight: .semibold)
    /// A drawer's or a sheet's own title, as a navigation bar's (iOS Headline); 16 with a mouse.
    static let title: Font = Font.system(.headline, weight: .semibold)
    /// A row's name and its value, the body (iOS Body); 16 with a mouse, a desktop's body size (it was 14, and the desktop panel read small: the UI audit, 2026-11-09).
    static let row: Font = Font.system(.body, weight: .regular)
    /// What is read rather than scanned: a summary, a paragraph (iOS Subheadline); 16 with a mouse.
    static let prose: Font = Font.system(.subheadline, weight: .regular)
    /// The line under a row's name (iOS Subheadline); 14 with a mouse.
    static let detail: Font = Font.system(.subheadline, weight: .regular)
    /// A section's line of help, a group's heading, a key (iOS Footnote); 13 with a mouse too, the least a desktop's words are.
    static let note: Font = Font.system(.footnote, weight: .regular)
    /// The panel's tabs' words (iOS Footnote).
    static let tab: Font = Font.system(.footnote, weight: .regular)
    /// The tab bar's words (iOS Caption 1, 12/16; the iOS audit's P3).
    static let tabBar: Font = Font.system(.caption, weight: .regular)
    /// A StatusBadge's word (Active, Closed, In the air): iOS's Caption 1 in semibold, 12 on 16, the same with a mouse.
    static let badge: Font = Font.system(.caption, weight: .semibold)
    /// A chip's category in a narrow column (iOS Caption 2).
    static let caption: Font = Font.system(.caption2, weight: .bold)
    /// A figure's name, an ident, a chip's word: the display face's capitals, spaced a tenth of an em (letterSpacing in em).
    static let label: Font = Font.system(.footnote, weight: .semibold)
    /// label's letter spacing in points (0.1em).
    static let labelTracking: CGFloat = 1.3
    /// A figure in the strip: 26 on 31, bold, tabular digits (the Flying screen's size). iOS scales it with Title 1.
    static var figure: Font { Font(UIFontMetrics(forTextStyle: .title1).scaledFont(for: UIFont.systemFont(ofSize: 26, weight: .bold))).monospacedDigit() }
    /// figure's size at the default text size, for @ScaledMetric(relativeTo: .title).
    static let figureSize: CGFloat = 26
}

enum WingtipSpace {
    static let unit: CGFloat = 4
    static let hairline: CGFloat = 1
    static let xxs: CGFloat = 2
    static let xs: CGFloat = 4
    static let sm: CGFloat = 8
    static let md: CGFloat = 12
    static let lg: CGFloat = 16
    static let xl: CGFloat = 24
    static let xxl: CGFloat = 32
}

enum WingtipRadius {
    static let base: CGFloat = 10
    static let cockpit: CGFloat = 8
    static let ink: CGFloat = 12
    static let badge: CGFloat = 7
    static let control: CGFloat = 14
    static let card: CGFloat = 18
    static let banner: CGFloat = 22
    static let dialog: CGFloat = 28
    static let sheet: CGFloat = 36
}

/// Motion: durations in seconds, curves as cubic-bezier points.
enum WingtipMotion {
    static let sheet: TimeInterval = 0.3
    static let sheetLeast: TimeInterval = 0.22
    static let sheetMost: TimeInterval = 0.35
    static let sheetEase = Animation.timingCurve(0, 0, 0.58, 1, duration: 0.3)
    static let sheetBackEase = Animation.timingCurve(0.2, 0.9, 0.3, 1, duration: 0.3)
    static let drawer: TimeInterval = 0.45
    static let drawerEase = Animation.timingCurve(0.32, 0.72, 0, 1, duration: 0.3)
    static let fade: TimeInterval = 0.2
    static let quick: TimeInterval = 0.15
    static let page: TimeInterval = 0.25
    static let skeletonPulse: TimeInterval = 1.5
}

/// The taps felt on a key action, as SwiftUI's sensory feedback
/// (`.sensoryFeedback(WingtipHaptic.altitude, trigger:)`); the system
/// leaves them out where the pilot has turned system haptics off.
enum WingtipHaptic {
    /// An altitude set: a wheel's detent, as a picker ticks.
    static let altitude: SensoryFeedback = .selection
    /// Direct To or Fly Here taken: the route has changed under the pilot.
    static let directTo: SensoryFeedback = .impact(weight: .medium)
    /// An alert or a copilot warning shown: felt as well as seen, in a busy cockpit.
    static let warning: SensoryFeedback = .warning
    /// The sheet settling at a detent (pill, half, full).
    static let detent: SensoryFeedback = .impact(weight: .light)
}

/// The map's camera and the zooms its marks change at (design/tokens.json's map group); pitches in degrees.
enum WingtipMap {
    static let pitchOpen: Double = 50
    static let pitchMax: Double = 85
    static let pitchFlatMax: Double = 60
    static let zoomStationClose: Double = 10
    static let zoomStationAlways: Double = 7
    static let zoomBarbFarFrom: Double = 6
    static let zoomBarbFull: Double = 9
    static let zoomWorldWind: Double = 4
    static let zoomStreakNear: Double = 7
    static let airspaceShadeMix: Double = 0.45
    static let airspaceShadeTopFt: Double = 10000
    static let airspaceFaded: Double = 0.35
    static let airspaceHeld: Double = 1.8
    static let airspaceLabelFaded: Double = 0.6
}

/// Model Weather's colour scales: ramps (value, colour, opacity in 255ths), the banded fields' opacities, and the covers.
enum WingtipFlow {
    typealias Stop = (at: Double, colour: UIColor, alpha: UInt8)
    static let rampWind: [Stop] = [(0, WingtipColor.Weather.flowWindCalm, 40), (25, WingtipColor.Weather.flowWindBreeze, 140), (50, WingtipColor.Weather.flowWindStrong, 190), (75, WingtipColor.Weather.flowWindGale, 220)]
